package com.filmorate.controller;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotNull;
import lombok.extern.slf4j.Slf4j;
import org.springframework.web.bind.annotation.*;
import com.filmorate.controller.util.ResponseTransfer;
import com.filmorate.model.Film;
import com.filmorate.model.FilmLike;
import com.filmorate.model.GenreType;
import com.filmorate.model.RatingType;
import com.filmorate.service.FilmService;

import java.util.List;

@Slf4j
@RestController
@RequestMapping("/films")
public class FilmController {

    /**
     * REST controller for managing films, likes, genres, and ratings.
     */
    private final FilmService filmService;

    public FilmController(FilmService filmService) {
        this.filmService = filmService;
    }

    @GetMapping
    public List<Film> getAllFilms() {
        log.info("GET /films — fetching all films");
        return filmService.getAllFilms();
    }

    @GetMapping("/{id}")
    public Film getFilmById(@PathVariable(value = "id") Integer filmId) {
        log.info("GET /films/{} — fetching film by ID", filmId);
        return filmService.getFilmById(filmId);
    }

    @PostMapping
    public Film addFilm(@RequestBody @NotNull @Valid Film film) {
        log.info("POST /films — adding film: {}", film.getName());
        return filmService.addFilm(film);
    }

    @PutMapping
    public Film updateFilm(@RequestBody @NotNull @Valid Film film) {
        log.info("PUT /films — updating film: {}", film.getId());
        return filmService.updateFilm(film);
    }

    @GetMapping("/{id}/like")
    public List<FilmLike> getLikesByFilmId(@PathVariable(value = "id") Integer filmId) {
        log.info("GET /films/{}/like — fetching likes", filmId);
        return filmService.getLikesByFilmId(filmId);
    }

    @PostMapping("/{id}/like/{userId}")
    public FilmLike addLike(@PathVariable(value = "id") Integer filmId,
                            @PathVariable Integer userId) {
        log.info("POST /films/{}/like/{} — adding like", filmId, userId);
        return filmService.addLike(filmId, userId);
    }

    @DeleteMapping("/{id}/like/{userId}")
    public ResponseTransfer deleteLike(@PathVariable(value = "id") Integer filmId,
                                       @PathVariable Integer userId) {
        log.info("DELETE /films/{}/like/{} — removing like", filmId, userId);
        filmService.deleteLike(filmId, userId);
        return new ResponseTransfer("Like deleted");
    }

    @GetMapping("/popular")
    public List<Film> findMostPopularFilms(@RequestParam(defaultValue = "10", required = false) Integer count) {
        log.info("GET /films/popular?count={} — fetching most popular films", count);
        return filmService.findMostPopularFilms(count);
    }

    @GetMapping("/genres")
    public List<GenreType> findAllGenres() {
        log.info("GET /films/genres — fetching all genres");
        return filmService.findAllGenres();
    }

    @GetMapping("/genres/{id}")
    public GenreType findGenreById(@PathVariable(value = "id") Integer genreId) {
        log.info("GET /films/genres/{} — fetching genre by ID", genreId);
        return filmService.findGenreById(genreId);
    }

    @GetMapping("/{id}/genres")
    public List<GenreType> findGenreByFilmId(@PathVariable(value = "id") Integer filmId) {
        log.info("GET /films/{}/genres — fetching genres by film ID", filmId);
        return filmService.findGenreByFilmId(filmId);
    }

    @PostMapping("/{id}/genres")
    public List<GenreType> addGenreToFilm(@PathVariable(value = "id") Integer filmId,
                                            @RequestBody @NotNull List<String> genreList) {
        log.info("POST /films/{}/genres — adding genres: {}", filmId, genreList);
        return filmService.addGenreToFilm(filmId, genreList);
    }

    @GetMapping("/mpa")
    public List<RatingType> findAllRatings() {
        log.info("GET /films/mpa — fetching all ratings");
        return filmService.findAllRatings();
    }

    @GetMapping("/mpa/{id}")
    public RatingType findRatingById(@PathVariable(value = "id") Integer ratingId) {
        log.info("GET /films/mpa/{} — fetching rating by ID", ratingId);
        return filmService.findRatingById(ratingId);
    }

    @GetMapping("{id}/mpa")
    public RatingType findRatingByFilmId(@PathVariable(value = "id") Integer filmId) {
        log.info("GET /films/{}/mpa — fetching rating by film ID", filmId);
        return filmService.findRatingByFilmId(filmId);
    }
}

package com.filmorate.controller;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotNull;
import lombok.extern.slf4j.Slf4j;
import org.springframework.web.bind.annotation.*;
import com.filmorate.controller.util.ResponseTransfer;
import com.filmorate.model.Friendship;
import com.filmorate.model.User;
import com.filmorate.service.UserService;

import java.util.List;

/**
 * REST controller for managing users and friends.
 */
@Slf4j
@RestController
@RequestMapping("/users")
public class UserController {

    private final UserService userService;

    public UserController(UserService userService) {
        this.userService = userService;
    }

    @GetMapping
    public List<User> getAllUsers() {
        log.info("GET /users — fetching all users");
        return userService.getAllUsers();
    }

    @GetMapping("/{id}")
    public User getUserById(@PathVariable(value = "id") Integer userId) {
        log.info("GET /users/{} — fetching user by ID", userId);
        return userService.getUserById(userId);
    }

    @PostMapping
    public User addUser(@RequestBody @NotNull @Valid User user) {
        log.info("POST /users — adding user: {}", user.getName());
        return userService.addUser(user);
    }

    @PutMapping
    public User updateUser(@RequestBody @NotNull @Valid User user) {
        log.info("PUT /users — updating user ID: {}", user.getId());
        return userService.updateUser(user);
    }

    @PutMapping("/{id}/friends/{friendId}")
    public Friendship addFriend(@PathVariable(value = "id") Integer userId,
                                @PathVariable Integer friendId) {
        log.info("PUT /{}/friends/{} — adding user: {} new friend: {}", userId, friendId, userId, friendId);
        return userService.addFriend(userId, friendId);
    }

    @DeleteMapping("/{id}/friends/{friendId}")
    public ResponseTransfer deleteFriend(@PathVariable(value = "id") Integer userId,
                                         @PathVariable Integer friendId) {
        log.info("DELETE {}/friends/{} — removing friend: {} by user: {}", userId, friendId, friendId, userId);
        userService.deleteFriend(userId, friendId);
        return new ResponseTransfer("Friend deleted");
    }

    @GetMapping("{id}/friends/common/{otherId}")
    public List<User> findCommonFriends(@PathVariable(value = "id") Integer userId,
                                        @PathVariable Integer otherId) {
        log.info("GET {}/friends/common/{} — fetching all common friends between " +
                "user: {} and other user: {}", userId, otherId, userId, otherId);
        return userService.findCommonFriends(userId, otherId);
    }

    @GetMapping("{id}/friends")
    public List<User> findFriends(@PathVariable(value = "id") Integer userId) {
        log.info("GET {}/friends — fetching all friends of user: {}", userId, userId);
        return userService.findFriends(userId);
    }
}

package com.filmorate.controller.util;

import lombok.Getter;
import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestControllerAdvice;
import com.filmorate.excepsion.*;
import com.filmorate.excepsion.film.FilmAlreadyExistException;
import com.filmorate.excepsion.film.FilmNotFoundException;
import com.filmorate.excepsion.filmLike.FilmLikeNotFoundException;
import com.filmorate.excepsion.friendship.FriendshipNotFoundException;
import com.filmorate.excepsion.gender.GenreAlreadyExistException;
import com.filmorate.excepsion.gender.GenreNotFoundException;
import com.filmorate.excepsion.rating.RatingNotFoundException;
import com.filmorate.excepsion.user.UserAlreadyExistException;
import com.filmorate.excepsion.user.UserNotFoundException;

/**
 * Global error handler for REST controllers.
 * Intercepts application-specific exceptions and transforms them into
 * consistent error responses with appropriate HTTP status codes.
 */
@RestControllerAdvice
public class ErrorHandler {

    /**
     * Handles generic "not found" exceptions.
     */
    @ExceptionHandler({
            NotFoundException.class,
            UserNotFoundException.class,
            FilmNotFoundException.class,
            FriendshipNotFoundException.class,
            GenreNotFoundException.class,
            RatingNotFoundException.class,
            FilmLikeNotFoundException.class
    })
    @ResponseStatus(HttpStatus.NOT_FOUND)
    public ErrorResponse handleNotFoundExceptions(final RuntimeException exception) {
        return buildErrorResponse(exception);
    }

    /**
     * Handles validation-related exceptions.
     */
    @ExceptionHandler({ValidationException.class, IncorrectParameterException.class})
    @ResponseStatus(HttpStatus.BAD_REQUEST)
    public ErrorResponse handleValidationExceptions(final RuntimeException exception) {
        if (exception instanceof IncorrectParameterException paramEx) {
            return new ErrorResponse("Validation error",
                    String.format("Please check field \"%s\"", paramEx.getParameter()));
        }
        return buildErrorResponse(exception);
    }

    /**
     * Handles "already exists" conflicts.
     */
    @ExceptionHandler({UserAlreadyExistException.class, FilmAlreadyExistException.class, GenreAlreadyExistException.class})
    @ResponseStatus(HttpStatus.CONFLICT)
    public ErrorResponse handleConflictExceptions(final RuntimeException exception) {
        return buildErrorResponse(exception);
    }

    /**
     * Builds a standard error response from an exception.
     */
    private ErrorResponse buildErrorResponse(Exception exception) {
        return new ErrorResponse(exception.getClass().getSimpleName(), exception.getMessage());
    }

    /**
     * Standardized error response object.
     */
    @Getter
    public static class ErrorResponse {
        private final String error;       // Error type (short name)
        private final String description; // Detailed error message

        public ErrorResponse(String error) {
            this(error, null);
        }

        public ErrorResponse(String error, String description) {
            this.error = error;
            this.description = description;
        }
    }
}

