package com.filmorate.model;

import com.fasterxml.jackson.annotation.JsonFormat;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Positive;
import jakarta.validation.constraints.Size;
import lombok.Data;

import java.time.LocalDate;

/**
 * Represents a film in the application.
 * <p>
 * Contains main metadata such as:
 * <ul>
 *   <li>id – unique identifier of the film</li>
 *   <li>name – title of the film</li>
 *   <li>description – short description (max 200 chars)</li>
 *   <li>rating – age rating (e.g. G, PG, R)</li>
 *   <li>releaseDate – official release date</li>
 *   <li>duration – duration in minutes (must be positive)</li>
 * </ul>
 */
@Data
public class Film {

    private int id;

    @NotBlank(message = "Name cannot be empty")
    private String name;

    @NotBlank(message = "Description cannot be empty")
    @Size(max = 200, message = "Description cannot be longer than 200 characters")
    private String description;

    @NotNull(message = "Rating cannot be null")
    private RatingType rating;

    @NotNull(message = "Release date cannot be null")
    @JsonFormat(pattern = "yyyy-MM-dd")
    private LocalDate releaseDate;

    @Positive(message = "Duration cannot be negative")
    private int duration;

    public Film(int id, String name, String description, RatingType rating, LocalDate releaseDate, int duration) {
        this.id = id;
        this.name = name;
        this.description = description;
        this.rating = rating;
        this.releaseDate = releaseDate;
        this.duration = duration;
    }
}

package com.filmorate.model;

import lombok.EqualsAndHashCode;
import lombok.Getter;
import lombok.ToString;

/**
 * Represents a "like" relation between a {@link User} and a {@link Film}.
 * <p>
 * Each instance means that a specific user liked a specific film.
 */
@Getter
@ToString
@EqualsAndHashCode
public class FilmLike {

    private final Film film;
    private final User user;

    public FilmLike(Film film, User user) {
        this.film = film;
        this.user = user;
    }
}

package com.filmorate.model;

import lombok.Getter;
import lombok.Setter;
import lombok.ToString;

/**
 * Represents a friendship relationship between two users.
 * <p>
 * Each instance contains:
 * <ul>
 *   <li>user – the user who sent the friend request</li>
 *   <li>friend – the user who confirms the friendship</li>
 *   <li>status – true if confirmed, false otherwise</li>
 * </ul>
 */
@Getter
@Setter
@ToString
public class Friendship {
    private Integer id;
    private final User user; // User who sends the friend request
    private final User friend; // User who confirms the friendship
    private Boolean status; // Friendship status: true = confirmed, false = pending

    public Friendship(User user, User friend, boolean status) {
        this.user = user;
        this.friend = friend;
        this.status = status;
    }

    public Friendship(int id, User user, User friend, boolean status) {
        this.id = id;
        this.user = user;
        this.friend = friend;
        this.status = status;
    }
}

package com.filmorate.model;

import lombok.Getter;
import lombok.Setter;

import java.util.HashSet;
import java.util.Set;

/**
 * Represents a genre of films.<br>
 * Each instance contains a genre type and a set of films that belong to this genre.
 */
// TODO: to implement methods
@Getter
@Setter
public class Genre {

    private final GenreType genreType;
    private final Set<Film> films;

    public Genre(GenreType genreType, Set<Film> films) {
        this.genreType = genreType;
        this.films = (films != null) ? films : new HashSet<>();
    }

    /**
     * Adds a film to this genre.
     *
     * @param film the film to add
     * @return true if the film was added, false if it was already present
     */
    public boolean addFilm(Film film) {
        return films.add(film);
    }

    /**
     * Removes a film from this genre.
     *
     * @param film the film to remove
     * @return true if the film was removed, false if it was not present
     */
    public boolean removeFilm(Film film) {
        return films.remove(film);
    }
}

