    @Override
    public List<Film> getAllFilms() {
        if (films.isEmpty()) {
            throw new FilmNotFoundException("No films available");
        }
        log.info("Retrieved {} films", films.size());
        return new ArrayList<>(films.values());
    }

    @Override
    public Film getFilmById(int id) {
        return Optional.ofNullable(films.get(id))
                .orElseThrow(() -> new FilmNotFoundException("Film with ID " + id + " not found"));
    }

    @Override
    public Film addFilm(Film film) {
        boolean exists = films.values().stream()
                .anyMatch(f -> f.getName().equals(film.getName())
                        && f.getReleaseDate().equals(film.getReleaseDate()));
        if (exists) {
            throw new FilmAlreadyExistException("Film already exists");
        }

        film.setId(generateFilmId());
        films.put(film.getId(), film);
        log.info("Saved film: {}", film);
        return film;
    }

    @Override
    public Film updateFilm(@NotNull @Valid Film film) {
        if (!films.containsKey(film.getId())) {
            throw new FilmNotFoundException("Film with ID " + film.getId() + " not found");
        }
        films.put(film.getId(), film);

        log.info("Updated film: {}", film);
        return film;
    }

    @Override
    public List<FilmLike> getLikesByFilmId(int filmId) {
        getFilmById(filmId); // ensure film exists

        List<FilmLike> foundFilmLikes = filmLikes.stream()
                .filter(filmLike -> filmLike.getFilm().getId() == filmId)
                .toList();

        if (foundFilmLikes.isEmpty()) {
            throw new FilmLikeNotFoundException("No likes for film with ID " + filmId);
        }

        log.info("Retrieved {} likes for film {}", foundFilmLikes.size(), filmId);
        return foundFilmLikes;
    }

    @Override
    public Optional<FilmLike> getFilmLike(int filmId, int userId) {
        return filmLikes.stream()
                .filter(filmLike -> filmLike.getFilm().getId() == filmId && filmLike.getUser().getId() == userId)
                .findFirst();
    }

    @Override
    public FilmLike addLike(int filmId, int userId) {
        Film film = getFilmById(userId); // ensure film exists
        User user = userStorage.getUserById(userId); // ensure user exists

        if (getFilmLike(filmId, userId).isPresent()) {
            throw new FilmLikeAlreadyExistException(
                    String.format("User %s already liked film %s", userId, filmId));
        }
        FilmLike filmLike = new FilmLike(film, user);
        filmLikes.add(filmLike);

        log.info("Added like: {}", filmLike);
        return filmLike;
    }

    @Override
    public void deleteLike(int filmId, int userId) {
        getFilmById(userId); // ensure film exists
        userStorage.getUserById(userId); // ensure user exists

        FilmLike filmLike = getFilmLike(filmId, userId)
                .orElseThrow(() -> new FilmLikeNotFoundException(
                        String.format("User %s has no like for film %s", userId, filmId)));

        filmLikes.remove(filmLike);
        log.info("Deleted like: {}", filmLike);
    }

    @Override
    public List<Film> findMostPopularFilms(int count) {
        Map<Film, Integer> mostPopularFilms = filmLikes.stream()
                .collect(Collectors.groupingBy(FilmLike::getFilm, summingInt(e -> 1)));

        log.info("Total liked films: {}", mostPopularFilms.size());

        return mostPopularFilms.entrySet()
                .stream()
                .sorted(Map.Entry.<Film, Integer>comparingByValue().reversed())
                .map(Map.Entry::getKey)
                .limit(count)
                .toList();
    }

    @Override
    public List<GenreType> findAllGenres() {
        if (filmGenres.isEmpty()) {
            throw new GenreNotFoundException("No genres available");
        }
        log.info("Retrieved {} genres", filmGenres.size());
        return filmGenres.values().stream().map(Genre::getGenreType).toList();
    }

    @Override
    public GenreType findGenreById(int genreId) {
        return Optional.ofNullable(filmGenres.get(genreId))
                .map(Genre::getGenreType)
                .orElseThrow(() -> new GenreNotFoundException("Genre with ID " + genreId + " not found"));
    }

    @Override
    public List<GenreType> findGenreByFilmId(int filmId) {
        getFilmById(filmId); // ensure film exists

        List<GenreType> genres = filmGenres.values().stream()
                .filter(genre -> genre.getFilms().contains(films.get(filmId)))
                .map(Genre::getGenreType)
                .toList();

        log.info("Retrieved {} genres for film {}", genres.size(), filmId);
        return genres;
    }

    @Override
    public List<GenreType> addGenreToFilm(int filmId, List<String> genreList) {
        Film film = getFilmById(filmId);

        for (String genreString : genreList) {
            GenreType genreType = transformGenreNameToGenreType(genreString);

            Genre genre = filmGenres.values().stream()
                    .filter(g -> g.getGenreType().equals(genreType))
                    .toList().getLast();

            if (genre.getFilms().contains(film)) {
                throw new GenreAlreadyExistException("Genre already exists by this film");
            }
            genre.getFilms().add(film);
        }
        return findGenreByFilmId(filmId);
    }

    @Override
    public List<RatingType> findAllRatings() {
        return Arrays.asList(RatingType.values());
    }

    @Override
    public RatingType findRatingById(int ratingId) {
        return Optional.ofNullable(ratingTypes.get(ratingId))
                .orElseThrow(() -> new RatingNotFoundException("Rating with ID " + ratingId + " not found"));
    }

    @Override
    public RatingType findRatingByFilmId(int filmId) {
        return films.get(filmId).getRating();
    }

    public int generateFilmId() {
        return filmNextId++;
    }

    //-----------------------
    //Private helpers methods
    //-----------------------

    private int generateGenreId() {
        return genreNextId++;
    }

    private int generateRatingId() {
        return ratingNextId++;
    }

    /**
     * Converts a string representation of a genre to a {@link GenreType}.
     *
     * @param genreString the genre string, e.g., "comedy", "drama"
     * @return the corresponding {@link GenreType}
     * @throws NotFoundException if no match is found
     */
    private GenreType transformGenreNameToGenreType(String genreString) {
        return switch (genreString) {
            case ("comedy") -> GenreType.COMEDY;
            case ("drama") -> GenreType.DRAMA;
            case ("cartoon") -> GenreType.CARTOON;
            case ("thriller") -> GenreType.THRILLER;
            case ("documentary") -> GenreType.DOCUMENTARY;
            case ("action") -> GenreType.ACTION;
            default -> throw new NotFoundException("No such GenreType found");
        };
    }
}

package com.filmorate.storage.user;

import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Repository;
import com.filmorate.excepsion.friendship.FriendshipAlreadyExistException;
import com.filmorate.excepsion.friendship.FriendshipNotFoundException;
import com.filmorate.excepsion.user.UserAlreadyExistException;
import com.filmorate.excepsion.user.UserNotFoundException;
import com.filmorate.model.Friendship;
import com.filmorate.model.User;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Optional;
import java.util.stream.Collectors;

/**
 * In-memory implementation of {@link UserStorage}.
 * <p>
 * Stores users and friendships in HashMaps.
 * Intended for testing and prototyping purposes.
 */
@Repository("inMemoryUserStorage")
@Slf4j
public class InMemoryUserStorage implements UserStorage {

    private final HashMap<Integer, User> users = new HashMap<>();
    private final HashMap<Integer, Friendship> friendships = new HashMap<>();

    private int nextUserId = 1;
    private int nextFriendshipId = 1;

    @Override
    public List<User> getAllUsers() {
        if (users.isEmpty()) {
            throw new UserNotFoundException("No users available");
        }
        log.info("Retrieved {} users", users.size());
        return new ArrayList<>(users.values());
    }

    @Override
    public User getUserById(int id) {
        return Optional.ofNullable(users.get(id))
                .orElseThrow(() -> new UserNotFoundException("User with ID " + id + " not found"));
    }

    @Override
    public User addUser(User user) {
        boolean exists = users.values().stream()
                .anyMatch(existingUser -> existingUser.getEmail().equals(user.getEmail()));

        if (exists) {
            throw new UserAlreadyExistException("User with email " + user.getEmail() + " already exists");
        }

        user.setId(generateUserId());
        users.put(user.getId(), user);

        log.info("Added user: {}", user);
        return user;
    }

    @Override
    public User updateUser(User user) {
        if (!users.containsKey(user.getId())) {
            throw new UserNotFoundException("User with ID " + user.getId() + " not found");
        }
        users.put(user.getId(), user);

        log.info("Updated user: {}", user);
        return user;
    }

    @Override
    public Friendship addFriend(Friendship friendship) {
        int userId = friendship.getUser().getId();
        int friendId = friendship.getFriend().getId();

        if (getFriendship(userId, friendId).isPresent()) {
            throw new FriendshipAlreadyExistException(
                    String.format("User %s already has user %s as friend", userId, friendId));
        }

        friendship.setId(generateFriendshipId());
        friendships.put(friendship.getId(), friendship);

        log.info("Added friendship: {}", friendship);
        return friendship;
    }
    @Override
    public void updateFriendship(Friendship friendship) {
        friendships.put(friendship.getId(), friendship);
        log.info("Updated friendship: {}", friendship);
    }

    @Override
    public Optional<Friendship> getFriendship(int userId, int friendId) {
        return friendships.values().stream()
                .filter(f -> f.getUser().getId() == userId && f.getFriend().getId() == friendId)
                .findFirst();
    }

    @Override
    public void deleteFriend(Friendship friendship) {
        friendships.remove(friendship.getId());
        log.info("Deleted friendship: {}", friendship);
    }

    @Override
    public List<User> findFriends(int userId) {
        getUserById(userId); // ensure user exists

        List<User> friends = friendships.values().stream()
                .filter(f -> f.getUser().getId() == userId)
                .map(Friendship::getFriend)
                .collect(Collectors.toList());

        if (friends.isEmpty()) {
            throw new FriendshipNotFoundException("User with ID " + userId + " has no friends");
        }

        log.info("Retrieved {} friends for user {}", friends.size(), userId);
        return friends;
    }

    //-----------------------
    //Private helpers methods
    //-----------------------

    private int generateUserId() {
        return nextUserId++;
    }

    private int generateFriendshipId() {
        return nextFriendshipId++;
    }
}

package com.filmorate.storage.user;

import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.jdbc.support.KeyHolder;
import org.springframework.stereotype.Repository;
import com.filmorate.excepsion.friendship.FriendshipAlreadyExistException;
import com.filmorate.excepsion.friendship.FriendshipNotFoundException;
import com.filmorate.excepsion.user.UserAlreadyExistException;
import com.filmorate.excepsion.user.UserNotFoundException;
import com.filmorate.model.Friendship;
import com.filmorate.model.User;

import java.sql.Date;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.time.LocalDate;
import java.util.List;
import java.util.Objects;
import java.util.Optional;
import java.util.stream.Collectors;

/**
 * Database-backed implementation of {@link UserStorage}.
 * <p>
 * Stores users and friendships in a relational database using {@link JdbcTemplate}.
 * Provides CRUD operations and friendship management.
 */
@Slf4j
@Repository("userDbStorage")
public class UserDbStorage implements UserStorage {

    private final JdbcTemplate jdbcTemplate;

    @Autowired
    public UserDbStorage(JdbcTemplate jdbcTemplate) {
        this.jdbcTemplate = jdbcTemplate;
    }

    @Override
    public List<User> getAllUsers() {
        String sql = "SELECT * FROM app_user ORDER BY id";
        List<User> allUsers = jdbcTemplate.query(sql, (rs, rowNum) -> makeUser(rs));

        log.info("Retrieved {} users", allUsers.size());
        return allUsers;
    }

    @Override
    public User getUserById(int id) {
        String sql = "SELECT * FROM app_user WHERE id=?";
        List<User> userList = jdbcTemplate.query(sql, (rs, rowNum) -> makeUser(rs), id);

        if (userList.isEmpty()) {
            throw new UserNotFoundException("No user under such ID found");
        }
        return userList.getLast();
    }

    @Override
    public User addUser(User user) {
        boolean exists = getAllUsers().stream()
                .anyMatch(u -> u.getEmail().equals(user.getEmail()));
        if (exists) {
            throw new UserAlreadyExistException("User with email " + user.getEmail() + " already exists");
        }

        String sql = "INSERT INTO app_user (login, name, email, birthday) " +
                     "VALUES (?, ?, ?, ?)";
        String login = user.getLogin();
        String name = user.getName();
        String email = user.getEmail();
        Date birthday = Date.valueOf(user.getBirthday());

        KeyHolder keyHolder = new GeneratedKeyHolder();
        int qnt = jdbcTemplate.update(connection -> {
            PreparedStatement stmt = connection.prepareStatement(sql, new String[]{"id"});
            stmt.setString(1, login);
            stmt.setString(2, name);
            stmt.setString(3, email);
            stmt.setDate(4, birthday);
            return stmt;
        }, keyHolder);
        log.info("Added {} new records to table app_user", qnt);

        int id = Objects.requireNonNull(keyHolder.getKey()).intValue();
        return getUserById(id);
    }

    @Override
    public User updateUser(User user) {
        getUserById(user.getId()); // ensure user exists

        String sql = "UPDATE app_user " +
                     "SET login=?, name=?, email=?, birthday=? " +
                     "WHERE id=?";
        String login = user.getLogin();
        String name = user.getName();
        String email = user.getEmail();
        Date birthday = Date.valueOf(user.getBirthday());
        int id = user.getId();

        int qnt = jdbcTemplate.update(sql, login, name, email, birthday, id);
        log.info("Updated {} records by table app_user", qnt);

        return getUserById(id);
    }

    @Override
    public Friendship addFriend(Friendship friendship) {
        int userId = friendship.getUser().getId();
        int friendId = friendship.getFriend().getId();

        if (getFriendship(userId, friendId).isPresent()) {
            throw new FriendshipAlreadyExistException(
                    String.format("User %s already has user %s as friend", userId, friendId));
        }

        String sql = "INSERT INTO friendship (user_id, friend_id, status) " +
                     "VALUES (?, ?, ?)";
        boolean status = friendship.getStatus();

        int qnt = jdbcTemplate.update(sql, userId, friendId, status);
        log.info("Added {} new records to table friendship", qnt);

        Optional<Friendship> newFriendship = getFriendship(userId, friendId);
        if (newFriendship.isEmpty()) {
            log.error("Friendship between {} and {} not found after adding to DB!", userId, friendId);
            throw new FriendshipNotFoundException(
                    String.format("Error by adding new friendship between %s and %s", userId, friendId));
        }
        return newFriendship.get();
    }

    @Override
    public void updateFriendship(Friendship friendship) {
        String sql = "UPDATE friendship " +
                     "SET status=? " +
                     "WHERE id=?";
        int id = friendship.getId();
        boolean status = friendship.getStatus();

        int qnt = jdbcTemplate.update(sql, status, id);
        log.info("Updated {} records by table friendship", qnt);
    }

    @Override
    public Optional<Friendship> getFriendship(int userId, int friendId) {
        String sql = "SELECT * FROM friendship WHERE user_id=? AND friend_id=?";
        List<Friendship> friendshipList = jdbcTemplate.query(sql, (rs, rowNum) -> makeFriendship(rs), userId, friendId);

        if (friendshipList.isEmpty()) {
            return Optional.empty();
        }
        return Optional.of(friendshipList.getLast());
    }

    @Override
    public void deleteFriend(Friendship friendship) {
        String sql = "DELETE FROM friendship WHERE id=?";
        int id = friendship.getId();

        int qnt = jdbcTemplate.update(sql, id);
        log.info("Deleted {} records from table friendship", qnt);
    }

    @Override
    public List<User> findFriends(int userId) {
        getUserById(userId); // ensure user exists

        String sql = "SELECT * FROM friendship WHERE user_id=?";
        List<Friendship> allFriendships = jdbcTemplate.query(sql, (rs, rowNum) -> makeFriendship(rs), userId);

        if (allFriendships.isEmpty()) {
            throw new FriendshipNotFoundException("User " + userId + " has no friends");
        }

        List<User> allFriends = allFriendships.stream()
                .map(Friendship::getFriend)
                .collect(Collectors.toList());

        log.info("Retrieved {} friends for user {}", allFriends.size(), userId);
        return allFriends;
    }

    //-----------------------
    //Private helpers methods
    //-----------------------

    /**
     * Maps a SQL result set to a {@link User} object.
     *
     * @param rs the ResultSet
     * @return a User object
     * @throws SQLException if mapping fails
     */
    private User makeUser(ResultSet rs) throws SQLException {
        int id = rs.getInt("id");
        String login = rs.getString("login");
        String name = rs.getString("name");
        String email = rs.getString("email");
        LocalDate birthday = rs.getDate("birthday").toLocalDate();

        return new User(id, login, name, email, birthday);
    }

    /**
     * Maps a SQL result set to a {@link Friendship} object.
     *
     * @param rs the ResultSet
     * @return a Friendship object
     * @throws SQLException if mapping fails
     */
    private Friendship makeFriendship(ResultSet rs) throws SQLException {
        int id = rs.getInt("id");
        int userId = rs.getInt("user_id");
        int friendId = rs.getInt("friend_id");
        boolean status = rs.getBoolean("status");

        return new Friendship(id, getUserById(userId), getUserById(friendId), status);
    }
}

package com.filmorate.storage.user;

import com.filmorate.model.Friendship;
import com.filmorate.model.User;

import java.util.List;
import java.util.Optional;

/**
 * Interface defining storage operations for {@link User} and {@link Friendship}.<br>
 * Implementations may store data in memory or in a database.
 */
public interface UserStorage {

    List<User> getAllUsers();

    User getUserById(int id);

    User addUser(User user);

    User updateUser(User user);

    Friendship addFriend(Friendship friendship);

    void updateFriendship(Friendship friendship);

    Optional<Friendship> getFriendship(int userId, int friendId);

    void deleteFriend(Friendship friendship);

    List<User> findFriends(int userId);
}

CREATE TABLE IF NOT EXISTS app_user (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  login varchar,
  name varchar,
  email varchar,
  birthday date
);

CREATE TABLE IF NOT EXISTS friendship (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id INTEGER REFERENCES app_user (id),
  friend_id INTEGER REFERENCES app_user (id),
  status boolean
);

CREATE TABLE IF NOT EXISTS rating (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name varchar
);

CREATE TABLE IF NOT EXISTS film (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name varchar,
  description text,
  rating_id INTEGER REFERENCES rating (id),
  release_date date,
  duration INTEGER
);

COMMENT ON COLUMN film.duration IS 'in_minutes';

CREATE TABLE IF NOT EXISTS film_like (
  user_id INTEGER REFERENCES app_user (id),
  film_id INTEGER REFERENCES film (id),
  PRIMARY KEY (user_id, film_id)
);

CREATE TABLE IF NOT EXISTS genre (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name varchar
);

CREATE TABLE IF NOT EXISTS film_genre (
  film_id INTEGER REFERENCES film (id),
  genre_id INTEGER REFERENCES genre (id),
  PRIMARY KEY (film_id, genre_id)
);

